function balancedStrings(n: number): string[] {
  const out: string[] = [];
  for (let mask = 0; mask < 1 << (2 * n); mask++) {
    let s = "", depth = 0;
    for (let i = 0; i < 2 * n && depth >= 0; i++) {
      const open = ((mask >> i) & 1) === 1;
      s += open ? "(" : ")";
      depth += open ? 1 : -1;
    }
    if (depth === 0 && s.length === 2 * n) out.push(s);
  }
  return out;
}

