class Solution:
    def balancedStrings(self, n: int) -> List[str]:
        out = []
        for mask in range(1 << (2 * n)):
            s, depth = [], 0
            for i in range(2 * n):
                is_open = (mask >> i) & 1
                s.append("(" if is_open else ")")
                depth += 1 if is_open else -1
                if depth < 0:
                    break
            if depth == 0 and len(s) == 2 * n:
                out.append("".join(s))
        return out

