function balancedStrings(n: number): string[] {
  const out: string[] = [];
  const cur: string[] = [];
  const go = (opens: number, closes: number): void => {
    if (cur.length === 2 * n) {
      out.push(cur.join(""));
      return;
    }
    if (opens < n) {
      cur.push("(");
      go(opens + 1, closes);
      cur.pop();
    }
    if (closes < opens) {
      cur.push(")");
      go(opens, closes + 1);
      cur.pop();
    }
  };
  go(0, 0);
  return out;
}

