function balancedStrings(n: number): string[] {
  const memo: string[][] = [[""]];
  for (let k = 1; k <= n; k++) {
    const list: string[] = [];
    for (let i = 0; i < k; i++) {
      for (const a of memo[i]) for (const b of memo[k - 1 - i]) list.push("(" + a + ")" + b);
    }
    memo.push(list);
  }
  return memo[n];
}

